INSERT INTO public.agent_configuration_catalog (key, definition)
SELECT item->>'key', item FROM jsonb_array_elements($catalog$[{"key": "contextualDiscoveryRules", "target": "policy", "attribute": "contextualDiscoveryRules", "default": "{\n  \"maxQuestions\": 10,\n  \"readyGroups\": [\n    [\n      \"brand\",\n      \"budget\"\n    ],\n    [\n      \"brand\",\n      \"style\",\n      \"case_size\"\n    ],\n    [\n      \"brand\",\n      \"occasion\",\n      \"case_size\"\n    ],\n    [\n      \"budget\",\n      \"attributes\"\n    ]\n  ],\n  \"directRequestPattern\": \"\\\\b(?:mostre|mande|envie)\\\\s+(?:as\\\\s+)?(?:opções|opcoes|modelos|lista)|\\\\b(?:pode buscar|pode pesquisar|sem perguntas|não quero responder|nao quero responder)\\\\b\",\n  \"questions\": [\n    {\n      \"slot\": \"model_intent\",\n      \"instruction\": \"Descubra se já tem um modelo em mente ou deseja uma indicação. Não repita a marca como pergunta.\",\n      \"fallback\": \"Você já tem algum modelo em mente ou gostaria de uma sugestão?\"\n    },\n    {\n      \"slot\": \"budget\",\n      \"instruction\": \"Pergunte cordialmente a faixa de investimento, sem pressionar.\",\n      \"fallback\": \"Qual faixa de investimento você tem em mente?\"\n    },\n    {\n      \"slot\": \"purchase_purpose\",\n      \"instruction\": \"Descubra se é para uso pessoal ou presente, somente quando o cliente procura uma indicação. Não deduza gênero pelo nome ou destinatário.\",\n      \"fallback\": \"É para você ou para presentear alguém?\"\n    },\n    {\n      \"slot\": \"gender\",\n      \"instruction\": \"Pergunte preferência por modelos masculinos, femininos ou unissex, aceitando sem preferência. Não deduza pelo gênero de quem compra.\",\n      \"fallback\": \"Você prefere modelos masculinos, femininos ou unissex?\"\n    },\n    {\n      \"slot\": \"style\",\n      \"instruction\": \"Descubra o estilo desejado. Dê poucos exemplos simples, como clássico, esportivo ou mergulho; aceite outros estilos do catálogo e sem preferência.\",\n      \"fallback\": \"Você prefere um estilo clássico, esportivo ou de mergulho?\"\n    },\n    {\n      \"slot\": \"occasion\",\n      \"instruction\": \"Descubra o uso ou ocasião, usando termos simples, como dia a dia, trabalho ou esporte.\",\n      \"fallback\": \"Você procura um relógio para o dia a dia, trabalho ou alguma ocasião especial?\"\n    },\n    {\n      \"slot\": \"case_size\",\n      \"instruction\": \"Pergunte preferência de tamanho. Aceite pequeno ou grande e não exija medida do pulso. Não converta gosto subjetivo em milímetros exatos.\",\n      \"fallback\": \"Você prefere um relógio menor e discreto ou uma caixa maior?\"\n    },\n    {\n      \"slot\": \"mechanism\",\n      \"instruction\": \"Descubra se prefere automático, mecânico manual ou quartzo. Se não conhecer, explique brevemente ou aceite sem preferência.\",\n      \"fallback\": \"Tem preferência por movimento automático, mecânico ou quartzo?\"\n    },\n    {\n      \"slot\": \"color\",\n      \"instruction\": \"Descubra a preferência de cor do mostrador se isso ajudar a escolher.\",\n      \"fallback\": \"Tem alguma preferência de cor para o mostrador?\"\n    },\n    {\n      \"slot\": \"strap\",\n      \"instruction\": \"Descubra a preferência de pulseira, diferenciando-a do material da caixa.\",\n      \"fallback\": \"Você prefere pulseira de metal, couro ou borracha?\"\n    }\n  ],\n  \"detailLimit\": 3\n}", "label": "Assuntos e regras de qualificação", "type": "textarea", "description": "JSON editável: questions define prioridade, instrução e contingência; readyGroups define combinações suficientes; maxQuestions limita perguntas; directRequestPattern libera pedidos diretos. detailLimit limita a confirmação de fichas incompletas por consulta (0 a 6).", "group": "Qualificação contextual", "readOnly": false, "maxLength": 16000}, {"key": "adaptiveDiscoveryRules", "target": "policy", "attribute": "adaptiveDiscoveryRules", "default": "{\n  \"reviewAfterQuestions\": 3,\n  \"maxSearches\": 4,\n  \"candidateLimit\": 20,\n  \"cacheTtlSeconds\": 300,\n  \"facets\": [\n    {\n      \"slot\": \"case_size\",\n      \"fields\": [\n        \"case_size\",\n        \"case_size_mm\"\n      ]\n    },\n    {\n      \"slot\": \"color\",\n      \"fields\": [\n        \"dial_color\",\n        \"color\"\n      ]\n    },\n    {\n      \"slot\": \"strap\",\n      \"fields\": [\n        \"strap_material\",\n        \"strap_type\",\n        \"bracelet_material\"\n      ]\n    },\n    {\n      \"slot\": \"budget\",\n      \"fields\": [\n        \"current_price\",\n        \"price\"\n      ]\n    },\n    {\n      \"slot\": \"occasion\",\n      \"fields\": [\n        \"occasion\"\n      ]\n    },\n    {\n      \"slot\": \"gender\",\n      \"fields\": [\n        \"gender\"\n      ]\n    },\n    {\n      \"slot\": \"style\",\n      \"fields\": [\n        \"style\"\n      ]\n    },\n    {\n      \"slot\": \"mechanism\",\n      \"fields\": [\n        \"mechanism\"\n      ]\n    }\n  ],\n  \"criteriaLabels\": {\n    \"brand\": \"marca\",\n    \"color\": \"mostrador\",\n    \"budget\": \"orçamento máximo\",\n    \"case_size\": \"tamanho\",\n    \"strap\": \"pulseira\",\n    \"mechanism\": \"movimento\",\n    \"crystal\": \"vidro\"\n  },\n  \"showResultsPattern\": \"\\\\b(?:mostra|mostre|manda|mande)\\\\s+(?:o que|as opções|as opcoes|os produtos)|\\\\b(?:pode escolher|sem mais perguntas)\\\\b\"\n}", "label": "Regras de consulta e progresso", "type": "textarea", "description": "JSON: reviewAfterQuestions é revisão, não limite obrigatório; maxSearches limita consultas preliminares por descoberta; candidateLimit e cacheTtlSeconds controlam volume e validade; facets define campos e prioridade em caso de empate.", "group": "Qualificação adaptativa", "readOnly": false, "maxLength": 12000}, {"key": "message.commerce_search_restarted", "target": "message", "attribute": "commerce_search_restarted", "default": "Claro, vamos começar uma nova busca. Você já tem algum modelo em mente ou gostaria de uma sugestão?", "label": "Confirmação de nova busca", "description": "Resposta ao pedido explícito de reiniciar; preserva cadastro e pedidos.", "group": "Qualificação contextual", "type": "textarea", "maxLength": 1000, "readOnly": false}]$catalog$::jsonb) item
ON CONFLICT (key) DO UPDATE SET definition=EXCLUDED.definition, updated_at=now();
